// ════════════════════════════════════════════════
//  PHYSICAL EXAMINATION MODULE (compact flowchart, multi-media cards)
//  A step (card) = category + title + sequence + optional stage_label
//  (shown as a labeled divider above the card, e.g. "Inspection") +
//  a list of media items. Each item has its own type:
//    - text:  has_toggle decides if it shows a Normal/Abnormal split
//    - image/gif/video/audio: always support a Normal/Abnormal toggle
//  Images/GIFs are uploaded or pasted (Ctrl+V); video/audio are pasted
//  URLs (YouTube links auto-embed) to keep storage lightweight.
//  "Done" checkmarks live in localStorage so they ride along in Full Backup.
// ════════════════════════════════════════════════
const PE_DEFAULT_CATEGORIES = { cvs: 'CVS Exam', respiratory: 'Respiratory Exam', abdominal: 'Abdominal Exam', neuro: 'Neuro Exam', msk: 'MSK Exam' };
// Icon + accent color per category, so the sidebar is scannable at a glance.
// Unknown/custom categories get a deterministic color from the fallback palette.
const PE_CATEGORY_STYLE = {
  cvs: { icon: '❤️', color: '#ef4444' },
  respiratory: { icon: '🫁', color: '#3b82f6' },
  abdominal: { icon: '🫃', color: '#22c55e' },
  neuro: { icon: '🧠', color: '#a78bfa' },
  msk: { icon: '🦴', color: '#f59e0b' },
};
const PE_CATEGORY_FALLBACK_COLORS = ['#14b8a6', '#ec4899', '#f97316', '#6366f1', '#84cc16', '#06b6d4'];
function peCategoryStyle(key) {
  if (PE_CATEGORY_STYLE[key]) return PE_CATEGORY_STYLE[key];
  let hash = 0;
  for (let i = 0; i < key.length; i++) hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  return { icon: '🩺', color: PE_CATEGORY_FALLBACK_COLORS[hash % PE_CATEGORY_FALLBACK_COLORS.length] };
}
let peSteps = [];
let peLoaded = false; // true only once idbGetAllPeSteps() (ALL categories) has run — kept strictly for backup/export, which genuinely needs everything
let peLoadedCategories = new Set(); // categories whose rows are present in peSteps via the lightweight per-category path
let peCategoryCounts = {}; // {category: count} — cheap, key-only, refreshed whenever the library view opens
let peCurrentId = null;
let peActiveCategory = localStorage.getItem('drmonic_pe_active_category') || 'cvs';
let pePendingItems = [];
let pePasteTarget = null; // { itemId, which }
let peCompleted = new Set(JSON.parse(localStorage.getItem('drmonic_pe_completed') || '[]'));
// Completed-step counts per category, kept as a small running tally (updated
// wherever a step's completion/category actually changes) so the sidebar can
// show "x/y done" per category WITHOUT having to load every category's full
// step data just to count checkmarks — that would defeat the lazy-loading fix.
let peCompletedCountByCategory = JSON.parse(localStorage.getItem('drmonic_pe_completed_by_cat') || '{}');
function savePeCompletedCountByCategory() {
  localStorage.setItem('drmonic_pe_completed_by_cat', JSON.stringify(peCompletedCountByCategory));
}

function peCategoryIsLoaded(cat) { return peLoaded || peLoadedCategories.has(cat); }

async function refreshPeCategoryCounts() {
  try { peCategoryCounts = await idbGetPeCategoryCounts(); }
  catch (e) { console.error('refreshPeCategoryCounts failed', e); }
}

// Pulls one category's rows (with their images) into peSteps, if not already there.
async function ensurePeCategoryLoaded(cat) {
  if (peCategoryIsLoaded(cat)) return;
  try {
    const rows = await idbGetPeStepsByCategory(cat);
    peSteps = peSteps.filter(s => s.category !== cat).concat(rows);
    peLoadedCategories.add(cat);
  } catch (e) {
    console.error('ensurePeCategoryLoaded failed', e);
    showToast('⚠️ تعذّر تحميل هذا القسم من التخزين — جرب تحديث الصفحة');
  }
}

function savePeCompleted() {
  localStorage.setItem('drmonic_pe_completed', JSON.stringify([...peCompleted]));
}

// ── PE hero image: an optional illustrative banner with 4 clickable
// "technique" hotspots (Inspection/Palpation/Percussion/Auscultation).
// Ships with a default image but the user can swap it, and can reposition
// the hotspot boxes by hand (drag-select) since they depend on wherever the
// labelled panels actually sit in whichever picture is loaded.
// ── PE hero image: an optional illustrative banner. The user defines any
// number of clickable regions on it by placing points one-by-one (like a
// Photoshop pen/lasso tool) and tagging each region with one of the ACTUAL
// stage_label values used in the active category — not a fixed list, since
// there can be more (or fewer) than the classic 4 exam techniques.
const PE_HERO_DEFAULT_IMG = 'data:image/jpeg;base64,';
let peHeroImageSrc = null;
let peHeroLoaded = false;
// Regions persist as {label, points:[[x,y],...]} in % coordinates (0-100).
let peHeroRegions = JSON.parse(localStorage.getItem('drmonic_pe_hero_regions') || '[]');
let peHeroEditMode = false;
let peHeroDrawingPoints = null; // array while actively placing points for a new region, else null

async function ensurePeHeroLoaded() {
  if (peHeroLoaded) return;
  peHeroLoaded = true;
  try {
    const saved = await idbGetMeta('pe_hero_image');
    peHeroImageSrc = saved || PE_HERO_DEFAULT_IMG;
  } catch (e) {
    console.error('ensurePeHeroLoaded failed', e);
    peHeroImageSrc = PE_HERO_DEFAULT_IMG;
  }
}

function savePeHeroRegions() {
  localStorage.setItem('drmonic_pe_hero_regions', JSON.stringify(peHeroRegions));
}

function peHeroPointsToStr(points) {
  return points.map(p => `${p[0]},${p[1]}`).join(' ');
}

function renderPeHero() {
  const wrap = document.getElementById('peHeroWrap');
  if (!wrap || !peHeroImageSrc) return;
  const stageOptions = (peLastGroups || []).map(g => `<option value="${esc(g.label)}">${esc(g.label)}</option>`).join('');
  const regionChips = peHeroRegions.map((r, idx) => `<span class="pe-hero-region-chip">${esc(r.label)}<button onclick="peHeroDeleteRegion(${idx})" title="\u062d\u0630\u0641">\u2715</button></span>`).join('');
  const toolbarLeft = peHeroEditMode ? `
      <select class="pe-hero-stage-select" id="peHeroStageSelect"${!peLastGroups || !peLastGroups.length ? ' disabled' : ''}>${stageOptions}</select>
      <button class="btn btn-ghost btn-sm" onclick="peHeroFinishRegion()" ${!peHeroDrawingPoints || peHeroDrawingPoints.length < 3 ? 'disabled' : ''}>\u2713 \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0634\u0643\u0644</button>
      <button class="btn btn-ghost btn-sm" onclick="peHeroCancelDrawing()">\u2715 \u0625\u0644\u063a\u0627\u0621</button>
      ${regionChips}` : '';
  wrap.innerHTML = `
    <div class="pe-hero-toolbar">
      <div class="pe-hero-toolbar-left">${toolbarLeft}</div>
      <button class="btn btn-ghost btn-sm" onclick="peHeroToggleEditMode()">${peHeroEditMode ? '\u2713 \u062a\u0645' : '\ud83d\udccd \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0648\u0627\u0642\u0639'}</button>
      <button class="btn btn-ghost btn-sm" onclick="peHeroChangeImageClick()">\ud83d\uddbc\ufe0f \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0635\u0648\u0631\u0629</button>
    </div>
    <div class="pe-hero-wrap ${peHeroEditMode ? 'pe-hero-editing' : ''}" id="peHeroImgWrap">
      <img src="${peHeroImageSrc}" alt="\u0635\u0648\u0631\u0629 \u062a\u0648\u0636\u064a\u062d\u064a\u0629" />
      <svg class="pe-hero-svg-overlay" viewBox="0 0 100 100" preserveAspectRatio="none">
        ${peHeroRegions.map((r, idx) => `<polygon class="pe-hero-region" points="${peHeroPointsToStr(r.points)}" onclick="peHeroRegionClick(${idx})"><title>${esc(r.label)}</title></polygon>`).join('')}
        ${peHeroEditMode && peHeroDrawingPoints && peHeroDrawingPoints.length ? `
          <polygon class="pe-hero-draw-line" points="${peHeroPointsToStr(peHeroDrawingPoints)}"></polygon>
          ${peHeroDrawingPoints.map(p => `<circle class="pe-hero-draw-dot" cx="${p[0]}" cy="${p[1]}" r="1.1"></circle>`).join('')}
        ` : ''}
      </svg>
      ${peHeroEditMode ? `<div class="pe-hero-edit-banner">${peHeroDrawingPoints ? `\u062f\u0648\u0633 \u0644\u0648\u0636\u0639 \u0646\u0642\u0627\u0637 (${peHeroDrawingPoints.length}) \u2014 \u0644\u0645\u0627 \u062a\u062e\u0644\u0635 \u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0648\u062f\u0648\u0633 \u2713 \u0625\u0646\u0647\u0627\u0621` : `\u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 ${!peLastGroups || !peLastGroups.length ? '(\u0627\u0641\u062a\u062d \u0642\u0633\u0645 \u0641\u064a\u0647 \u062e\u0637\u0648\u0627\u062a \u0623\u0648\u0644\u0627\u064b)' : ''} \u062b\u0645 \u062f\u0648\u0633 \u0639\u0644\u0649 \u0627\u0644\u0635\u0648\u0631\u0629 \u0644\u062a\u062d\u0637 \u0646\u0642\u0627\u0637`}</div>` : ''}
      <div class="pe-hero-overlay" id="peHeroOverlay">
        <div class="pe-hero-overlay-panel">
          <div class="pe-hero-overlay-head">
            <div class="pe-hero-overlay-title" id="peHeroOverlayTitle"></div>
            <button class="pe-hero-overlay-close" onclick="peHeroCloseOverlay()">\u2715</button>
          </div>
          <div class="pe-step-grid" id="peHeroOverlayGrid"></div>
        </div>
      </div>
    </div>`;
  if (peHeroEditMode) attachPeHeroDrawHandler();
}

function peHeroToggleEditMode() {
  peHeroEditMode = !peHeroEditMode;
  peHeroDrawingPoints = null;
  renderPeHero();
}

function peHeroDeleteRegion(idx) {
  peHeroRegions.splice(idx, 1);
  savePeHeroRegions();
  renderPeHero();
}

function peHeroCancelDrawing() {
  peHeroDrawingPoints = null;
  renderPeHero();
}

function peHeroFinishRegion() {
  if (!peHeroDrawingPoints || peHeroDrawingPoints.length < 3) return;
  const select = document.getElementById('peHeroStageSelect');
  const label = select?.value || '';
  if (!label) {
    showToast('\u26a0\ufe0f \u0627\u062e\u062a\u0631 \u0645\u0631\u062d\u0644\u0629 \u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0623\u0648\u0644\u0627\u064b (\u0644\u0627\u0632\u0645 \u062a\u0641\u062a\u062d \u0642\u0633\u0645 \u0641\u064a\u0647 \u062e\u0637\u0648\u0627\u062a \u0645\u0631\u062a\u0628\u0629 \u0628\u0640 Stage Label \u0623\u0648\u0644\u0627\u064b)');
    return;
  }
  peHeroRegions.push({ label, points: peHeroDrawingPoints });
  savePeHeroRegions();
  peHeroDrawingPoints = null;
  renderPeHero();
}

// Point-by-point polygon drawing: each click/tap on the image adds a vertex.
function attachPeHeroDrawHandler() {
  const imgWrap = document.getElementById('peHeroImgWrap');
  if (!imgWrap) return;
  imgWrap.onclick = (e) => {
    if (e.target.closest('.pe-hero-toolbar')) return;
    const rect = imgWrap.getBoundingClientRect();
    const x = Math.round(Math.min(Math.max((e.clientX - rect.left) / rect.width, 0), 1) * 1000) / 10;
    const y = Math.round(Math.min(Math.max((e.clientY - rect.top) / rect.height, 0), 1) * 1000) / 10;
    if (!peHeroDrawingPoints) peHeroDrawingPoints = [];
    peHeroDrawingPoints.push([x, y]);
    renderPeHero();
  };
}

// Clicking a finished region blurs the hero image and shows that stage's
// actual step list (from the active category) as an overlay right on top —
// matched by exact stage_label first, then a loose contains-match fallback.
function peHeroRegionClick(idx) {
  if (peHeroEditMode) return;
  const region = peHeroRegions[idx];
  if (!region) return;
  const groups = peLastGroups || [];
  let gi = groups.findIndex(g => g.label === region.label);
  if (gi === -1) gi = groups.findIndex(g => g.label.toLowerCase().includes(region.label.toLowerCase()) || region.label.toLowerCase().includes(g.label.toLowerCase()));
  if (gi === -1) {
    showToast(`\u26a0\ufe0f \u0645\u0627 \u0644\u0642\u064a\u062a \u062e\u0637\u0648\u0627\u062a \u0628\u0647\u0630\u0627 \u0627\u0644\u0642\u0633\u0645 \u062a\u062d\u062a "${region.label}" \u0628\u0639\u062f`);
    return;
  }
  const g = groups[gi];
  document.getElementById('peHeroOverlayTitle').textContent = g.label;
  const grid = document.getElementById('peHeroOverlayGrid');
  grid.innerHTML = g.steps.map(s => peStepCardHtml(s, peCompleted.has(s.id))).join('');
  document.getElementById('peHeroImgWrap')?.classList.add('pe-hero-open');
  document.getElementById('peHeroOverlay')?.classList.add('open');
  hydratePeFsMedia(grid);
  grid.querySelectorAll('.pe-item-writable-text').forEach(peAutoGrowTextarea);
}

function peHeroCloseOverlay() {
  document.getElementById('peHeroImgWrap')?.classList.remove('pe-hero-open');
  document.getElementById('peHeroOverlay')?.classList.remove('open');
}

function peHeroChangeImageClick() {
  document.getElementById('peHeroFileInput')?.click();
}

function peHeroImageFileChosen(input) {
  const file = input.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    compressImageDataUrl(reader.result, async (compressed) => {
      peHeroImageSrc = compressed;
      try { await idbSetMeta('pe_hero_image', compressed); } catch (e) { console.error('save hero image failed', e); }
      renderPeHero();
      showToast('\u2705 \u062a\u0645 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0635\u0648\u0631\u0629');
    }, 1400, 0.82);
  };
  reader.readAsDataURL(file);
  input.value = '';
}


async function loadPeSteps() {
  try {
    peSteps = await idbGetAllPeSteps();
  } catch (e) {
    console.error('loadPeSteps failed', e);
    showToast('⚠️ تعذّر تحميل بيانات الفحص السريري من التخزين — جرب تحديث الصفحة');
    return; // keep whatever was already in memory instead of wiping it to []
  }
  peLoaded = true;
}

function peAllCategories() {
  const custom = [...new Set([...Object.keys(peCategoryCounts), ...peSteps.map(s => s.category)].filter(Boolean))];
  const merged = { ...PE_DEFAULT_CATEGORIES };
  custom.forEach(c => { if (!merged[c]) merged[c] = c; });
  return merged;
}

async function showPeLibraryView() {
  hideAllViews();
  document.getElementById('peLibraryView').classList.add('active');
  // Cheap: key-only counts for every category, then only the active
  // category's actual rows (incl. images) — not the whole library.
  await refreshPeCategoryCounts();
  await ensurePeCategoryLoaded(peActiveCategory);
  peShowFlowchart();
}

function peShowFlowchart() {
  peCurrentId = null;
  document.getElementById('peFormArea').style.display = 'none';
  document.getElementById('peFlowchartArea').style.display = 'block';
  document.getElementById('peCategoryRow').style.display = 'flex';
  document.getElementById('peToolbar').style.display = 'flex';
  document.getElementById('peBackBtn').textContent = '← الرجوع';
  document.getElementById('peBackBtn').onclick = showHome;
  renderPeCategoryRow();
  renderPeFlowchart();
  ensurePeHeroLoaded().then(renderPeHero);
}

function renderPeCategoryRow() {
  const row = document.getElementById('peCategoryRow');
  const cats = peAllCategories();
  row.innerHTML = Object.entries(cats).map(([key, label]) => {
    const total = peCategoryCounts[key] ?? peSteps.filter(s => s.category === key).length;
    const done = peCompletedCountByCategory[key] || 0;
    const pct = total ? Math.round((Math.min(done, total) / total) * 100) : 0;
    const style = peCategoryStyle(key);
    const active = peActiveCategory === key;
    return `
      <button class="pe-sidebar-item ${active ? 'active' : ''}" style="--pe-accent:${style.color}" onclick="peSetCategory('${key}')">
        <span class="pe-sidebar-ring" style="background:conic-gradient(${style.color} ${pct}%, var(--border) ${pct}% 100%)"><span class="pe-sidebar-ring-inner">${style.icon}</span></span>
        <span class="pe-sidebar-label">
          <span class="pe-sidebar-name">${esc(label)}</span>
          <span class="pe-sidebar-count">${total ? `${done}/${total}` : 'فاضي'}</span>
        </span>
      </button>`;
  }).join('') + `<button class="pe-sidebar-item pe-sidebar-add" onclick="peAddCategoryPrompt()"><span class="pe-sidebar-ring" style="--pe-accent:var(--text2);background:var(--navy2)"><span class="pe-sidebar-ring-inner">➕</span></span><span class="pe-sidebar-label"><span class="pe-sidebar-name">قسم جديد</span></span></button>`;
}

function peAddCategoryPrompt() {
  const name = prompt('اسم القسم الجديد (مثال: Skin Exam):');
  if (!name || !name.trim()) return;
  const key = name.trim().toLowerCase().replace(/\s+/g, '_');
  PE_DEFAULT_CATEGORIES[key] = name.trim();
  peActiveCategory = key;
  peLoadedCategories.add(key); // brand-new, nothing in IDB to fetch yet
  renderPeCategoryRow();
  renderPeFlowchart();
}

async function peSetCategory(cat) {
  peActiveCategory = cat;
  localStorage.setItem('drmonic_pe_active_category', cat);
  renderPeCategoryRow();
  if (!peCategoryIsLoaded(cat)) {
    document.getElementById('peFlowchartArea').innerHTML = `<div class="pe-empty-category"><div style="font-size:2.5rem;">⏳</div><h3>جاري التحميل...</h3></div>`;
  }
  await ensurePeCategoryLoaded(cat);
  renderPeFlowchart();
}

let peOpenStages = new Map(); // "category::groupIndex" -> bool (persists while the tab is open)
let peLastGroups = []; // the stage groups from the most recent render, so the hero-image hotspots can look one up by keyword

function renderPeFlowchart() {
  const area = document.getElementById('peFlowchartArea');
  document.getElementById('peListCount').textContent = '';
  const steps = peSteps.filter(s => s.category === peActiveCategory).sort((a, b) => (a.sequence || 0) - (b.sequence || 0));
  if (!steps.length) {
    document.getElementById('peStepper').innerHTML = '';
    peLastGroups = [];
    area.innerHTML = `<div class="pe-empty-category"><div style="font-size:2.5rem;">🩺</div><h3>لا توجد خطوات بهذا القسم بعد</h3><p>اضغط "➕ إضافة خطوة" لتبدأ تبني تسلسل الفحص</p></div>`;
    renderPeHero();
    return;
  }
  // Group into accordion sections by stage_label (steps without one land in a
  // single "خطوات عامة" section). Order follows first appearance by sequence.
  const groups = [];
  const byLabel = new Map();
  steps.forEach(s => {
    const label = s.stage_label || 'خطوات عامة';
    let g = byLabel.get(label);
    if (!g) { g = { label, steps: [] }; byLabel.set(label, g); groups.push(g); }
    g.steps.push(s);
  });
  peLastGroups = groups;
  renderPeStepper(groups);
  area.innerHTML = groups.map((g, gi) => {
    const stageKey = `${peActiveCategory}::${gi}`;
    const isOpen = peOpenStages.has(stageKey) ? peOpenStages.get(stageKey) : (gi === 0);
    const doneCount = g.steps.filter(s => peCompleted.has(s.id)).length;
    const pct = g.steps.length ? Math.round((doneCount / g.steps.length) * 100) : 0;
    return `
      <div class="pe-stage-section" id="peStageSection_${gi}">
        <div class="pe-stage-connector">
          ${gi > 0 ? '<div class="pe-arrow">↓</div>' : ''}
          <div class="pe-stage-pill ${isOpen ? 'open' : ''}" onclick="peToggleStage('${stageKey}')">
            <span class="pe-stage-ring" style="background:conic-gradient(#06251f ${pct}%, rgba(6,37,31,0.28) ${pct}% 100%)"><span class="pe-stage-ring-inner">${doneCount}/${g.steps.length}</span></span>
            <span>${esc(g.label)}</span>
            <span class="pe-stage-chev">▾</span>
          </div>
          ${isOpen ? '<div class="pe-arrow">↓</div>' : ''}
        </div>
        <div class="pe-stage-body ${isOpen ? 'open' : ''}">
          ${isOpen ? peSmartBuilderHtml(g.label) : ''}
          <div class="pe-step-grid">${g.steps.map(s => peStepCardHtml(s, peCompleted.has(s.id))).join('')}</div>
        </div>
      </div>`;
  }).join('');
  hydratePeFsMedia(area);
  area.querySelectorAll('.pe-item-writable-text').forEach(peAutoGrowTextarea);
  renderPeHero(); // keeps the stage-picker options in sync whenever groups change (category switch, new step, etc.)
}

function peSmartBuilderHtml(stageLabel) {
  const label = String(stageLabel || '');
  const low = label.toLowerCase();
  let types;
  if (low.includes('percussion')) {
    types = ['percussion_map', 'text'];
  } else if (low.includes('auscult')) {
    types = ['auscultation_map', 'audio', 'text'];
  } else if (low.includes('inspection') || low.includes('inspect')) {
    types = ['text', 'image', 'image_group', 'checklist', 'comparison'];
  } else {
    types = ['text', 'image', 'image_group', 'hotspot_map', 'comparison'];
  }
  const labels = {
    text: '📝 Text finding',
    image: '🖼️ Image finding',
    image_group: '🖼️ Image group',
    checklist: '☑️ Checklist',
    hotspot_map: '📍 Hotspot map',
    percussion_map: '👋 Percussion map',
    auscultation_map: '🩺 Auscultation map',
    audio: '🎧 Audio spot',
    comparison: '✅/🚩 Comparison'
  };
  const encodedStage = encodeURIComponent(label);
  return `<div class="pe-smart-builder">${types.map(t => `<button type="button" class="btn btn-ghost btn-sm" onclick="peSmartAdd('${t}','${encodedStage}')">${labels[t]}</button>`).join('')}</div>`;
}

// Circular mini-map of the active category's stages, mirroring the style of
// the sidebar's progress rings — click a circle to jump straight to that
// stage's section (opening it if it's collapsed).
function renderPeStepper(groups) {
  const stepper = document.getElementById('peStepper');
  if (!stepper) return;
  if (groups.length < 2) { stepper.innerHTML = ''; return; }
  stepper.innerHTML = groups.map((g, gi) => {
    const stageKey = `${peActiveCategory}::${gi}`;
    const isOpen = peOpenStages.has(stageKey) ? peOpenStages.get(stageKey) : (gi === 0);
    const doneCount = g.steps.filter(s => peCompleted.has(s.id)).length;
    const complete = g.steps.length > 0 && doneCount === g.steps.length;
    return `${gi > 0 ? '<div class="pe-stepper-line"></div>' : ''}
      <div class="pe-stepper-item ${isOpen ? 'open' : ''} ${complete ? 'complete' : ''}" onclick="peJumpToStage('${stageKey}', ${gi})">
        <div class="pe-stepper-circle">${complete ? '✓' : gi + 1}</div>
        <div class="pe-stepper-label">${esc(g.label)}</div>
      </div>`;
  }).join('');
}

function peJumpToStage(stageKey, gi) {
  peOpenStages.set(stageKey, true);
  renderPeFlowchart();
  requestAnimationFrame(() => {
    document.getElementById('peStageSection_' + gi)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
}

function peToggleStage(stageKey) {
  const currentlyOpen = peOpenStages.has(stageKey) ? peOpenStages.get(stageKey) : stageKey.endsWith('::0');
  peOpenStages.set(stageKey, !currentlyOpen);
  renderPeFlowchart();
}

const PE_ITEM_ICONS = { text: '📝', image: '🖼️', gif: '🎞️', video: '🎬', audio: '🎧', hotspot_image: '📍' };
const PE_HOTSPOT_ICON_SRC = {
  auscultation: 'D:/Clinical/صور للموقع/Ausc.png',
  percussion: 'D:/Clinical/صور للموقع/perc.png',
};

function peStepCardHtml(s, done) {
  const items = s.media_items || [];
  return `
    <div class="pe-step-card pe-compact ${done ? 'pe-done' : ''}" id="peCard_${s.id}">
      <div class="pe-step-head">
        <div class="pe-step-check ${done ? 'checked' : ''}" onclick="peToggleDone('${s.id}')">${done ? '✓' : ''}</div>
        <div class="pe-step-title-wrap">
          <div class="pe-step-seq">#${s.sequence ?? ''}</div>
          <div class="pe-step-title">${esc(s.title || 'خطوة بدون عنوان')}</div>
        </div>
        <div class="pe-step-actions">
          <button class="btn btn-ghost btn-sm" style="padding:4px 8px;font-size:0.72rem;" onclick="peEditStep('${s.id}')">✏️</button>
          <button class="btn btn-ghost btn-sm" style="padding:4px 8px;font-size:0.72rem;color:var(--red);" onclick="peDeleteStep('${s.id}')">🗑️</button>
        </div>
      </div>
      ${items.length ? `<div class="pe-media-items">${peStepMediaHtml(s.id, items)}</div>` : ''}
    </div>`;
}

// Groups consecutive image/gif items into a side-by-side grid instead of
// each one taking a full-width row of its own; text/video/audio items stay
// as individual blocks in the normal flow.
function peStepMediaHtml(stepId, items) {
  const groups = [];
  let imgGroup = null;
  items.forEach(item => {
    if (item.type === 'image' || item.type === 'gif') {
      if (!imgGroup) { imgGroup = []; groups.push({ kind: 'images', items: imgGroup }); }
      imgGroup.push(item);
    } else {
      imgGroup = null;
      groups.push({ kind: 'single', item });
    }
  });
  return groups.map(g => {
    if (g.kind === 'images') {
      if (g.items.length === 1) return peMediaItemViewHtml(stepId, g.items[0]);
      return `<div class="pe-img-grid">${g.items.map(it => peMediaItemViewHtml(stepId, it)).join('')}</div>`;
    }
    return peMediaItemViewHtml(stepId, g.item);
  }).join('');
}

function peMediaItemViewHtml(stepId, item) {
  const showsToggle = item.has_toggle === true || (item.has_toggle == null && item.type !== 'text' && item.type !== 'hotspot_image');
  const icon = PE_ITEM_ICONS[item.type] || '📝';
  const toggleHtml = showsToggle ? `
    <div class="pe-item-toggle">
      <button class="pe-na-mini normal active" id="peItemNormalBtn_${item.id}" onclick="peToggleItemFinding('${stepId}','${item.id}','normal')">✅</button>
      <button class="pe-na-mini abnormal" id="peItemAbnormalBtn_${item.id}" onclick="peToggleItemFinding('${stepId}','${item.id}','abnormal')">🚩</button>
    </div>` : '';
  return `
    <div class="pe-media-item" data-item-id="${item.id}" data-item-type="${item.type}">
      <div class="pe-item-head"><span class="pe-item-icon">${icon}</span>${toggleHtml}</div>
      <div class="pe-item-body" id="peItemBody_${item.id}">${peItemContentHtml(stepId, item, 'normal')}</div>
    </div>`;
}

function peItemContentHtml(stepId, item, which) {
  const content = which === 'abnormal' ? item.abnormal_content : item.normal_content;
  if (item.type === 'hotspot_image') return peHotspotImageViewHtml(stepId, item);
  if (item.type === 'text' && item.writable) {
    return `<textarea class="pe-item-writable-text" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="اكتب هنا مباشرة (كيبورد أو قلم)..." oninput="peWriteItemContent('${stepId}','${item.id}','${which}',this.value);peAutoGrowTextarea(this);">${esc(content || '')}</textarea>`;
  }
  if (!content) return `<div class="pe-item-empty">—</div>`;
  if (item.type === 'text') {
    // Collapsed by default — text items are the ones that make a card tall,
    // so they only expand when the user actually wants to read them.
    return `<div class="pe-item-text-toggle" id="peTextToggle_${item.id}" onclick="peToggleTextCollapse('${item.id}')"><span class="chev">▾</span><span class="label">عرض النص</span></div><div class="pe-item-text-body" id="peText_${item.id}"><div class="pe-item-text">${hl(esc(content))}</div></div>`;
  }
  if (item.type === 'image' || item.type === 'gif') {
    const images = Array.isArray(content) ? content : (content ? [content] : []);
    return `<div class="pe-img-grid">${images.map(src => `<img class="pe-item-media-img" src="${src}" loading="lazy" decoding="async" onclick="event.stopPropagation();openLightbox('${String(src).replace(/'/g,"\\'")}')" alt="" />`).join('')}</div>`;
  }
  if (item.type === 'video') {
    if (content.startsWith('fs-handle:')) {
      return `<div class="pe-fs-media-wrap" data-fs-kind="video" data-fs-handle-id="${content.slice(10)}"></div>`;
    }
    const yt = extractYoutubeId(content);
    if (yt) return `<iframe class="note-youtube-embed pe-item-media-video" loading="lazy" src="https://www.youtube.com/embed/${yt}" allowfullscreen></iframe>`;
    const dr = extractDriveFileId(content);
    if (dr) return `<iframe class="note-youtube-embed pe-item-media-video" loading="lazy" src="https://drive.google.com/file/d/${dr}/preview" allowfullscreen></iframe>`;
    return `<video class="pe-item-media-video" src="${content}" controls preload="metadata"></video>`;
  }
  if (item.type === 'audio') {
    if (content.startsWith('fs-handle:')) {
      return `<div class="pe-fs-media-wrap" data-fs-kind="audio" data-fs-handle-id="${content.slice(10)}"></div>`;
    }
    return `<audio class="sound-audio-player" style="margin:0;" controls src="${content}"></audio>`;
  }
  return '';
}

function peHotspotImageViewHtml(stepId, item) {
  const src = item.base_image || item.normal_content || '';
  if (!src) return `<div class="pe-item-empty">—</div>`;
  const spots = Array.isArray(item.hotspots) ? item.hotspots : [];
  const payload = encodeURIComponent(JSON.stringify({ src, spots }));
  return `
    <div class="pe-hotspot-wrap">
      <img class="pe-item-media-img" src="${src}" loading="lazy" decoding="async" onclick="event.stopPropagation();openPeHotspotLightbox('${payload}')" alt="" />
      ${spots.map((spot, idx) => `<button class="pe-hotspot-pin ${spot.kind || 'percussion'}" style="left:${Number(spot.x) || 50}%;top:${Number(spot.y) || 50}%;" onclick="event.stopPropagation();peToggleHotspot('${item.id}',${idx})" title="${esc(spot.label || '')}"><img src="${PE_HOTSPOT_ICON_SRC[spot.kind] || PE_HOTSPOT_ICON_SRC.percussion}" alt="" /></button>`).join('')}
    </div>
    ${spots.map((spot, idx) => `<div class="pe-hotspot-pop" id="peHotspot_${item.id}_${idx}">
      ${spot.text ? `<div class="pe-item-text">${hl(esc(spot.text))}</div>` : ''}
      ${spot.image ? `<img class="pe-item-media-img" src="${spot.image}" onclick="event.stopPropagation();openLightbox('${String(spot.image).replace(/'/g,"\\'")}')" alt="" />` : ''}
      ${spot.audio ? `<audio class="sound-audio-player" style="margin:8px 0 0;" controls src="${spot.audio}"></audio>` : ''}
    </div>`).join('')}`;
}

function peToggleHotspot(itemId, idx) {
  document.querySelectorAll(`[id^="peHotspot_${itemId}_"]`).forEach(el => {
    if (el.id !== `peHotspot_${itemId}_${idx}`) el.classList.remove('open');
  });
  document.getElementById(`peHotspot_${itemId}_${idx}`)?.classList.toggle('open');
}

function openPeHotspotLightbox(payload) {
  let data;
  try { data = JSON.parse(decodeURIComponent(payload)); } catch (e) { return; }
  const box = document.getElementById('imgLightbox');
  const img = document.getElementById('imgLightboxImg');
  if (!box || !img) return;
  img.style.display = 'none';
  box.classList.add('open');
  box.innerHTML = `
    <div class="pe-hotspot-wrap" style="max-width:94vw;max-height:92vh;" onclick="event.stopPropagation()">
      <img class="pe-item-media-img" src="${data.src}" style="max-height:92vh;width:auto;max-width:94vw;" alt="" />
      ${(data.spots || []).map(spot => `<span class="pe-hotspot-pin ${spot.kind || 'percussion'}" style="left:${Number(spot.x) || 50}%;top:${Number(spot.y) || 50}%;"><img src="${PE_HOTSPOT_ICON_SRC[spot.kind] || PE_HOTSPOT_ICON_SRC.percussion}" alt="" /></span>`).join('')}
    </div>`;
}

function peToggleTextCollapse(itemId) {
  const body = document.getElementById('peText_' + itemId);
  const toggle = document.getElementById('peTextToggle_' + itemId);
  if (!body || !toggle) return;
  const open = body.classList.toggle('open');
  toggle.classList.toggle('open', open);
  const label = toggle.querySelector('.label');
  if (label) label.textContent = open ? 'إخفاء النص' : 'عرض النص';
}

// Grows a writable textarea to fit its content (up to 60vh) instead of
// always reserving a fixed block of space regardless of how little is typed.
function peAutoGrowTextarea(el) {
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, window.innerHeight * 0.6) + 'px';
}


/* Resolves data-fs-handle-id placeholders left by peItemContentHtml into a
   real <video>/<audio> element, requesting file-read permission if needed. */
function hydratePeFsMedia(scopeEl) {
  const root = scopeEl || document;
  root.querySelectorAll('.pe-fs-media-wrap[data-fs-handle-id]').forEach(async wrap => {
    if (wrap.dataset.hydrated) return;
    wrap.dataset.hydrated = '1';
    const id = wrap.dataset.fsHandleId;
    const kind = wrap.dataset.fsKind;
    const handle = await idbGetFsHandle(id).catch(() => null);
    if (!handle) {
      wrap.innerHTML = `<div class="pe-item-empty">⚠️ الملف مش موجود (اترفع من قرص PC ومحتاج تعيد ربطه)</div>`;
      return;
    }
    try {
      let perm = await handle.queryPermission({ mode: 'read' });
      if (perm !== 'granted') {
        wrap.innerHTML = `<button class="btn btn-ghost btn-sm" type="button">🔓 اضغط للسماح بعرض الملف من القرص</button>`;
        wrap.querySelector('button').onclick = async () => {
          const p = await handle.requestPermission({ mode: 'read' });
          if (p === 'granted') { wrap.dataset.hydrated = ''; hydratePeFsMedia(wrap.parentElement || root); }
          else showToast('⚠️ رفض الإذن — الملف ما رح يظهر');
        };
        return;
      }
      const file = await handle.getFile();
      const url = URL.createObjectURL(file);
      wrap.innerHTML = kind === 'audio'
        ? `<audio class="sound-audio-player" style="margin:0;" controls src="${url}"></audio>`
        : `<video class="pe-item-media-video" src="${url}" controls></video>`;
    } catch (e) {
      wrap.innerHTML = `<div class="pe-item-empty">⚠️ تعذّر فتح الملف من القرص (ممكن يكون انحذف أو انقل)</div>`;
    }
  });
}

function peToggleItemFinding(stepId, itemId, which) {
  const s = peSteps.find(x => x.id === stepId);
  const item = s?.media_items?.find(it => it.id === itemId);
  if (!item) return;
  document.getElementById(`peItemNormalBtn_${itemId}`)?.classList.toggle('active', which === 'normal');
  document.getElementById(`peItemAbnormalBtn_${itemId}`)?.classList.toggle('active', which === 'abnormal');
  const body = document.getElementById(`peItemBody_${itemId}`);
  body.innerHTML = peItemContentHtml(stepId, item, which);
  body.querySelectorAll('.pe-item-writable-text').forEach(peAutoGrowTextarea);
}

function peToggleDone(id) {
  const step = peSteps.find(s => s.id === id);
  if (peCompleted.has(id)) peCompleted.delete(id); else peCompleted.add(id);
  savePeCompleted();
  const done = peCompleted.has(id);
  if (step) {
    peCompletedCountByCategory[step.category] = Math.max(0, (peCompletedCountByCategory[step.category] || 0) + (done ? 1 : -1));
    savePeCompletedCountByCategory();
  }
  const card = document.getElementById('peCard_' + id);
  const check = card?.querySelector('.pe-step-check');
  card?.classList.toggle('pe-done', done);
  if (check) { check.classList.toggle('checked', done); check.textContent = done ? '✓' : ''; }
  renderPeCategoryRow();
}

function peDeleteStep(id) {
  const idx = peSteps.findIndex(s => s.id === id);
  if (idx < 0) return;
  const removed = peSteps[idx];
  const wasDone = peCompleted.has(id);
  peSteps.splice(idx, 1);
  idbDeletePeStep(id);
  peCategoryCounts[removed.category] = Math.max(0, (peCategoryCounts[removed.category] || 1) - 1);
  if (wasDone) peCompletedCountByCategory[removed.category] = Math.max(0, (peCompletedCountByCategory[removed.category] || 1) - 1);
  savePeCompletedCountByCategory();
  renderPeCategoryRow();
  renderPeFlowchart();
  showUndoToast('تم حذف الخطوة', async () => {
    peSteps.splice(idx, 0, removed);
    await idbPutPeStep(removed);
    peCategoryCounts[removed.category] = (peCategoryCounts[removed.category] || 0) + 1;
    if (wasDone) { peCompletedCountByCategory[removed.category] = (peCompletedCountByCategory[removed.category] || 0) + 1; savePeCompletedCountByCategory(); }
    renderPeCategoryRow();
    renderPeFlowchart();
  });
}

function peNewStep() { peOpenForm(null); }
function peEditStep(id) { peOpenForm(id); }

function peOpenForm(id, preset = null) {
  peCurrentId = id;
  const entry = id ? peSteps.find(s => s.id === id) : null;
  pePendingItems = entry ? JSON.parse(JSON.stringify(entry.media_items || [])) : (preset?.media_items ? JSON.parse(JSON.stringify(preset.media_items)) : []);
  pePasteTarget = null;
  document.getElementById('peFlowchartArea').style.display = 'none';
  document.getElementById('peCategoryRow').style.display = 'none';
  document.getElementById('peToolbar').style.display = 'none';
  document.getElementById('peBackBtn').textContent = '← رجوع للفحص';
  document.getElementById('peBackBtn').onclick = peShowFlowchart;
  document.getElementById('peListCount').textContent = '';
  const cats = peAllCategories();
  const area = document.getElementById('peFormArea');
  area.style.display = 'block';
  area.innerHTML = `
    <div class="pe-media-row">
      <div class="ecg-field">
        <label class="ecg-label">📁 Category</label>
        <select class="pe-media-type-select" id="peCategoryInput">
          ${Object.entries(cats).map(([val, label]) => `<option value="${val}" ${(entry?.category || preset?.category || peActiveCategory) === val ? 'selected' : ''}>${esc(label)}</option>`).join('')}
        </select>
      </div>
      <div class="ecg-field">
        <label class="ecg-label">🔢 Step Sequence Number</label>
        <input class="form-input" id="peSequenceInput" type="number" placeholder="1" value="${entry?.sequence ?? preset?.sequence ?? ''}" />
      </div>
    </div>
    <div class="ecg-field">
      <label class="ecg-label">🏷️ Step Title</label>
      <input class="form-input" id="peTitleInput" placeholder="مثال: Inspection of Hands / Clubbing" value="${(entry?.title || preset?.title || '').replace(/"/g,'&quot;')}" />
    </div>
    <div class="ecg-field">
      <label class="ecg-label">🔖 Stage Label (اختياري — نص يظهر على السهم فوق البطاقة، مثل Inspection / Palpation / Percussion / Auscultation)</label>
      <input class="form-input" id="peStageLabelInput" placeholder="Inspection" value="${(entry?.stage_label || preset?.stage_label || '').replace(/"/g,'&quot;')}" />
    </div>
    <div class="ecg-field">
      <label class="ecg-label">🎬 Media Items List</label>
      <div id="pePendingItemsList"></div>
      <div class="pe-add-item-row">
        <button type="button" class="btn btn-ghost btn-sm" onclick="peAddItem('text')">📝 + نص</button>
        <button type="button" class="btn btn-ghost btn-sm" onclick="peAddItem('image')">🖼️ + صورة</button>
        <button type="button" class="btn btn-ghost btn-sm" onclick="peAddItem('hotspot_image')">📍 + Perc/Ausc صورة</button>
        <button type="button" class="btn btn-ghost btn-sm" onclick="peAddItem('gif')">🎞️ + GIF</button>
        <button type="button" class="btn btn-ghost btn-sm" onclick="peAddItem('video')">🎬 + فيديو</button>
        <button type="button" class="btn btn-ghost btn-sm" onclick="peAddItem('audio')">🎧 + صوت</button>
      </div>
    </div>
    <div class="hx-save-bar">
      <button class="btn btn-primary" onclick="peSaveStep()">💾 حفظ الخطوة</button>
      <button class="btn btn-ghost" onclick="peShowFlowchart()">إلغاء</button>
    </div>`;
  renderPePendingItemsForm();
}

function peAddItem(type) {
  pePendingItems.push(peCreateMediaItem(type));
  renderPePendingItemsForm();
}

function peCreateMediaItem(type, overrides = {}) {
  return {
    id: 'item_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7),
    type,
    has_toggle: false,
    writable: false,
    normal_content: '',
    abnormal_content: '',
    base_image: '',
    hotspots: [],
    ...overrides,
  };
}

function peSmartAdd(type, encodedStage) {
  const stageLabel = decodeURIComponent(encodedStage || '');
  const nextSeq = (peSteps.filter(s => s.category === peActiveCategory).reduce((m, s) => Math.max(m, Number(s.sequence) || 0), 0) || 0) + 1;
  const preset = {
    category: peActiveCategory,
    sequence: nextSeq,
    stage_label: stageLabel,
    title: '',
    media_items: [],
  };
  if (type === 'text') {
    preset.title = stageLabel ? `${stageLabel} finding` : 'Text finding';
    preset.media_items = [peCreateMediaItem('text')];
  } else if (type === 'image') {
    preset.title = stageLabel ? `${stageLabel} image` : 'Image finding';
    preset.media_items = [peCreateMediaItem('image')];
  } else if (type === 'image_group') {
    preset.title = stageLabel ? `${stageLabel} image group` : 'Image group';
    preset.media_items = [peCreateMediaItem('image')];
  } else if (type === 'checklist') {
    preset.title = stageLabel ? `${stageLabel} checklist` : 'Checklist';
    preset.media_items = [peCreateMediaItem('text', { normal_content: '- ', writable: true })];
  } else if (type === 'comparison') {
    preset.title = stageLabel ? `${stageLabel} comparison` : 'Normal/Abnormal comparison';
    preset.media_items = [peCreateMediaItem('image', { has_toggle: true })];
  } else if (type === 'percussion_map') {
    preset.title = stageLabel || 'Percussion map';
    preset.media_items = [peCreateMediaItem('hotspot_image', { active_hotspot_kind: 'percussion' })];
  } else if (type === 'auscultation_map') {
    preset.title = stageLabel || 'Auscultation map';
    preset.media_items = [peCreateMediaItem('hotspot_image', { active_hotspot_kind: 'auscultation' })];
  } else if (type === 'hotspot_map') {
    preset.title = stageLabel ? `${stageLabel} hotspot map` : 'Hotspot map';
    preset.media_items = [peCreateMediaItem('hotspot_image')];
  } else if (type === 'audio') {
    preset.title = stageLabel ? `${stageLabel} audio` : 'Audio spot';
    preset.media_items = [peCreateMediaItem('audio')];
  }
  peOpenForm(null, preset);
}

function peRemoveItem(itemId) {
  pePendingItems = pePendingItems.filter(it => it.id !== itemId);
  renderPePendingItemsForm();
}

function peUpdateItemField(itemId, field, value) {
  const item = pePendingItems.find(it => it.id === itemId);
  if (item) item[field] = value;
}

function peToggleItemHasToggle(itemId, checked) {
  const item = pePendingItems.find(it => it.id === itemId);
  if (item) item.has_toggle = checked;
  renderPePendingItemsForm();
}

function peToggleItemWritable(itemId, checked) {
  const item = pePendingItems.find(it => it.id === itemId);
  if (item) item.writable = checked;
  renderPePendingItemsForm();
}

let pePendingWriteSave = null;
function peWriteItemContent(stepId, itemId, which, value) {
  const step = peSteps.find(s => s.id === stepId);
  const item = step?.media_items?.find(it => it.id === itemId);
  if (!item) return;
  item[which === 'abnormal' ? 'abnormal_content' : 'normal_content'] = value;
  clearTimeout(pePendingWriteSave);
  pePendingWriteSave = setTimeout(() => { if (step) idbPutPeStep(step); }, 700);
}

function peItemFormFieldsHtml(item) {
  if (item.type === 'text') {
    return `
      <label class="hx-checkbox-row" style="margin-bottom:10px;">
        <input type="checkbox" ${item.has_toggle ? 'checked' : ''} onchange="peToggleItemHasToggle('${item.id}', this.checked)" />
        <span>فعّل خياري ✅ Normal / 🚩 Abnormal لهذا النص</span>
      </label>
      <label class="hx-checkbox-row" style="margin-bottom:10px;">
        <input type="checkbox" ${item.writable ? 'checked' : ''} onchange="peToggleItemWritable('${item.id}', this.checked)" />
        <span>✍️ كتابة (بقدر تكتب مباشرة على البطاقة من صفحة العرض، بالكيبورد أو بالقلم)</span>
      </label>
      <textarea class="form-textarea" rows="2" placeholder="${item.has_toggle ? 'Normal text...' : 'النص...'}" oninput="peUpdateItemField('${item.id}','normal_content',this.value)">${esc(item.normal_content || '')}</textarea>
      ${item.has_toggle ? `<textarea class="form-textarea" rows="2" style="margin-top:8px;" placeholder="Abnormal text..." oninput="peUpdateItemField('${item.id}','abnormal_content',this.value)">${esc(item.abnormal_content || '')}</textarea>` : ''}`;
  }
  if (item.type === 'image' || item.type === 'gif') {
    return `
      <label class="hx-checkbox-row" style="margin-bottom:10px;">
        <input type="checkbox" ${item.has_toggle ? 'checked' : ''} onchange="peToggleItemHasToggle('${item.id}', this.checked)" />
        <span>فعل مقارنة Normal / Abnormal (اختياري)</span>
      </label>
      ${item.has_toggle ? `<div class="pe-media-row">${peImageSlotHtml(item, 'normal')}${peImageSlotHtml(item, 'abnormal')}</div>` : peImageSlotHtml(item, 'normal', true)}`;
  }
  if (item.type === 'hotspot_image') {
    return peHotspotItemFormHtml(item);
  }
  // video / audio — URL, or upload directly from device
  const ph = item.type === 'video' ? 'رابط يوتيوب أو Google Drive أو رابط فيديو مباشر...' : 'رابط ملف صوتي مباشر...';
  const accept = item.type === 'video' ? 'video/*' : 'audio/*';
  const uploadRow = (which) => `
    <input type="file" id="peItemMediaFile_${item.id}_${which}" accept="${accept}" style="display:none;" onchange="peItemMediaUpload('${item.id}','${which}',this.files)" />
    <button type="button" class="btn btn-ghost btn-sm" style="margin-top:6px;font-size:0.72rem;" onclick="document.getElementById('peItemMediaFile_${item.id}_${which}').click()">📁 ارفع من الجهاز</button>
    ${typeof window.showOpenFilePicker === 'function' ? `<button type="button" class="btn btn-ghost btn-sm" style="margin-top:6px;font-size:0.72rem;" onclick="peItemPickFromDisk('${item.id}','${which}','${item.type}')" title="PC فقط — بيربط الملف من القرص بدون ما ينسخه">💻 من القرص (بدون نسخ)</button>` : ''}`;
  return `
    <label class="hx-checkbox-row" style="margin-bottom:10px;">
      <input type="checkbox" ${item.has_toggle ? 'checked' : ''} onchange="peToggleItemHasToggle('${item.id}', this.checked)" />
      <span>فعل مقارنة Normal / Abnormal (اختياري)</span>
    </label>
    <div class="pe-media-row">
      <div>
        <label class="ecg-label" style="font-size:0.8rem;">${item.has_toggle ? '✅ Normal' : 'الملف'}</label>
        <input class="form-input" placeholder="${ph}" value="${(item.normal_content || '').replace(/"/g,'&quot;')}" oninput="peUpdateItemField('${item.id}','normal_content',this.value)" />
        ${uploadRow('normal')}
      </div>
      <div style="${item.has_toggle ? '' : 'display:none;'}">
        <label class="ecg-label" style="font-size:0.8rem;">🚩 Abnormal</label>
        <input class="form-input" placeholder="${ph}" value="${(item.abnormal_content || '').replace(/"/g,'&quot;')}" oninput="peUpdateItemField('${item.id}','abnormal_content',this.value)" />
        ${uploadRow('abnormal')}
      </div>
    </div>`;
}

async function peItemPickFromDisk(itemId, which, itemType) {
  try {
    const types = itemType === 'video'
      ? [{ description: 'Video', accept: { 'video/*': ['.mp4', '.mov', '.webm', '.mkv', '.avi'] } }]
      : [{ description: 'Audio', accept: { 'audio/*': ['.mp3', '.wav', '.m4a', '.ogg'] } }];
    const [handle] = await window.showOpenFilePicker({ types, multiple: false });
    const handleId = genId();
    await idbPutFsHandle(handleId, handle);
    peUpdateItemField(itemId, which === 'abnormal' ? 'abnormal_content' : 'normal_content', `fs-handle:${handleId}`);
    renderPePendingItemsForm();
    showToast('💻 اترّبط بالملف من القرص — لسا لازم تضغط "💾 حفظ الخطوة"');
  } catch (e) {
    if (e.name !== 'AbortError') { console.error('peItemPickFromDisk failed', e); showToast('⚠️ تعذّر فتح منتقي الملفات'); }
  }
}
function peItemMediaUpload(itemId, which, fileList) {
  const file = fileList?.[0];
  if (!file) return;
  const input = document.getElementById(`peItemMediaFile_${itemId}_${which}`);
  if (input) input.value = '';
  const sizeMB = file.size / 1024 / 1024;
  if (sizeMB > 15) {
    const ok = confirm(`⚠️ الملف حجمه ${sizeMB.toFixed(1)}MB — الملفات الكبيرة ممكن يفشل حفظها بصمت على بعض الأجهزة.\n\nالأفضل: استخدم رابط يوتيوب أو Google Drive بدل الرفع (حقل النص فوق زر الرفع).\n\nبدك تكمل الرفع رغم هيك؟`);
    if (!ok) return;
  }
  const reader = new FileReader();
  reader.onload = e => {
    peUpdateItemField(itemId, which === 'abnormal' ? 'abnormal_content' : 'normal_content', e.target.result);
    renderPePendingItemsForm();
    showToast('📎 الملف اتحمّل بالفورم — لسا لازم تضغط "💾 حفظ الخطوة" تحت عشان يتثبّت فعليًا');
  };
  reader.onerror = () => showToast('⚠️ تعذّرت قراءة الملف');
  reader.readAsDataURL(file);
}

function peImageSlotHtml(item, which, multiple = false) {
  const val = which === 'abnormal' ? item.abnormal_content : item.normal_content;
  const label = multiple ? 'الصور' : (which === 'abnormal' ? '🚩 Abnormal' : '✅ Normal');
  const vals = Array.isArray(val) ? val : (val ? [val] : []);
  return `
    <div>
      <label class="ecg-label" style="font-size:0.8rem;">${label}</label>
      <input type="file" id="peItemFile_${item.id}_${which}" accept="image/*" ${multiple ? 'multiple' : ''} style="display:none;" onchange="peItemImageUpload('${item.id}','${which}',this.files,${multiple ? 'true' : 'false'})" />
      <div onclick="pePasteTarget={itemId:'${item.id}',which:'${which}'}" tabindex="0">
        ${vals.length
          ? `<div class="pe-img-grid">${vals.map(src => `<img class="ecg-image-preview" src="${src}" onclick="pePasteTarget={itemId:'${item.id}',which:'${which}'};document.getElementById('peItemFile_${item.id}_${which}').click()" alt="" />`).join('')}</div>`
          : `<div class="ecg-image-drop" style="padding:16px;font-size:0.82rem;" onclick="pePasteTarget={itemId:'${item.id}',which:'${which}'};document.getElementById('peItemFile_${item.id}_${which}').click()">📁 ارفع أو الصق (Ctrl+V)</div>`}
      </div>
    </div>`;
}

function peHotspotItemFormHtml(item) {
  const spots = Array.isArray(item.hotspots) ? item.hotspots : [];
  const activeKind = item.active_hotspot_kind || 'percussion';
  return `
    <div>
      <label class="ecg-label" style="font-size:0.8rem;">صورة الفحص الأساسية</label>
      <input type="file" id="peItemFile_${item.id}_base" accept="image/*" style="display:none;" onchange="peItemImageUpload('${item.id}','base',this.files,false)" />
      ${item.base_image
        ? `<img class="ecg-image-preview" src="${item.base_image}" onclick="document.getElementById('peItemFile_${item.id}_base').click()" alt="" />`
        : `<div class="ecg-image-drop" style="padding:16px;font-size:0.82rem;" onclick="document.getElementById('peItemFile_${item.id}_base').click()">📁 ارفع صورة Chest / Abdomen / أي منطقة</div>`}
    </div>
    <div class="pe-add-item-row">
      <button type="button" class="btn ${activeKind === 'percussion' ? 'btn-primary' : 'btn-ghost'} btn-sm" onclick="peSetHotspotKind('${item.id}','percussion')">👋 Percussion cursor</button>
      <button type="button" class="btn ${activeKind === 'auscultation' ? 'btn-primary' : 'btn-ghost'} btn-sm" onclick="peSetHotspotKind('${item.id}','auscultation')">🩺 Auscultation cursor</button>
    </div>
    ${item.base_image ? `
      <div class="pe-hotspot-editor" onclick="peAddHotspotFromClick('${item.id}', event)">
        <img class="base" src="${item.base_image}" alt="" />
        ${spots.map((spot, idx) => `<button type="button" class="pe-hotspot-pin ${spot.kind || 'percussion'}" style="left:${Number(spot.x) || 50}%;top:${Number(spot.y) || 50}%;" onclick="event.stopPropagation();peSelectHotspot('${item.id}',${idx})"><img src="${PE_HOTSPOT_ICON_SRC[spot.kind] || PE_HOTSPOT_ICON_SRC.percussion}" alt="" /></button>`).join('')}
      </div>` : ''}
    ${spots.map((spot, idx) => `
      <div class="pe-form-item" style="margin-top:8px;">
        <div class="pe-form-item-head">
          <span>${spot.kind === 'auscultation' ? '🩺 Auscultation' : '👋 Percussion'} spot</span>
          <button type="button" class="btn btn-ghost btn-sm" style="padding:4px 8px;font-size:0.72rem;color:var(--red);" onclick="peRemoveHotspot('${item.id}',${idx})">🗑️ حذف</button>
        </div>
        <textarea class="form-textarea" rows="2" style="margin-top:8px;" placeholder="الكلام الي يطلع لما أكبس..." oninput="peUpdateHotspot('${item.id}',${idx},'text',this.value)">${esc(spot.text || '')}</textarea>
        <input class="form-input" style="margin-top:8px;" placeholder="رابط صورة للجواب (اختياري)" value="${(spot.image || '').replace(/"/g,'&quot;')}" oninput="peUpdateHotspot('${item.id}',${idx},'image',this.value)" />
        ${spot.kind === 'auscultation' ? `
          <input class="form-input" style="margin-top:8px;" placeholder="رابط فويس/Audio (اختياري)" value="${(spot.audio || '').replace(/"/g,'&quot;')}" oninput="peUpdateHotspot('${item.id}',${idx},'audio',this.value)" />
          <input type="file" id="peHotspotAudio_${item.id}_${idx}" accept="audio/*" style="display:none;" onchange="peUploadHotspotAudio('${item.id}',${idx},this.files)" />
          <button type="button" class="btn btn-ghost btn-sm" style="margin-top:8px;" onclick="document.getElementById('peHotspotAudio_${item.id}_${idx}').click()">🎧 ارفع فويس من الجهاز</button>
        ` : ''}
      </div>`).join('')}`;
}

function peSetHotspotKind(itemId, kind) {
  const item = pePendingItems.find(it => it.id === itemId);
  if (!item) return;
  item.active_hotspot_kind = kind;
  renderPePendingItemsForm();
}

function peAddHotspotFromClick(itemId, event) {
  const item = pePendingItems.find(it => it.id === itemId);
  const img = event.currentTarget.querySelector('img.base');
  if (!item || !img) return;
  const rect = img.getBoundingClientRect();
  const x = Math.round(Math.min(Math.max((event.clientX - rect.left) / rect.width, 0), 1) * 1000) / 10;
  const y = Math.round(Math.min(Math.max((event.clientY - rect.top) / rect.height, 0), 1) * 1000) / 10;
  if (!Array.isArray(item.hotspots)) item.hotspots = [];
  item.hotspots.push({ kind: item.active_hotspot_kind || 'percussion', x, y, text: '', image: '', audio: '' });
  renderPePendingItemsForm();
}

function peSelectHotspot(itemId, idx) {
  const item = pePendingItems.find(it => it.id === itemId);
  const spot = item?.hotspots?.[idx];
  if (!spot) return;
  item.active_hotspot_kind = spot.kind || 'percussion';
  renderPePendingItemsForm();
}

function peRemoveHotspot(itemId, idx) {
  const item = pePendingItems.find(it => it.id === itemId);
  if (!item || !Array.isArray(item.hotspots)) return;
  item.hotspots.splice(idx, 1);
  renderPePendingItemsForm();
}

function peUpdateHotspot(itemId, idx, field, value) {
  const item = pePendingItems.find(it => it.id === itemId);
  const spot = item?.hotspots?.[idx];
  if (!spot) return;
  spot[field] = field === 'x' || field === 'y' ? Math.max(0, Math.min(100, Number(value) || 0)) : value;
}

function peUploadHotspotAudio(itemId, idx, fileList) {
  const file = fileList?.[0];
  if (!file) return;
  const input = document.getElementById(`peHotspotAudio_${itemId}_${idx}`);
  if (input) input.value = '';
  const sizeMB = file.size / 1024 / 1024;
  if (sizeMB > 8 && !confirm(`حجم الفويس ${sizeMB.toFixed(1)}MB، ممكن يكبر الحفظ. بدك تكمل؟`)) return;
  const reader = new FileReader();
  reader.onload = e => {
    peUpdateHotspot(itemId, idx, 'audio', e.target.result);
    renderPePendingItemsForm();
    showToast('✅ تم رفع الفويس للسبوت — لا تنسى تحفظ الخطوة');
  };
  reader.onerror = () => showToast('⚠️ تعذرت قراءة ملف الصوت');
  reader.readAsDataURL(file);
}

function renderPePendingItemsForm() {
  const wrap = document.getElementById('pePendingItemsList');
  if (!wrap) return;
  if (!pePendingItems.length) {
    wrap.innerHTML = `<div class="pe-empty-category" style="padding:20px;">لا توجد عناصر ميديا بعد — ضيف وحدة من الأزرار تحت</div>`;
    return;
  }
  wrap.innerHTML = pePendingItems.map(item => `
    <div class="pe-form-item">
      <div class="pe-form-item-head">
        <span>${PE_ITEM_ICONS[item.type] || '📝'} ${item.type.toUpperCase()}</span>
        <button type="button" class="btn btn-ghost btn-sm" style="padding:4px 8px;font-size:0.72rem;color:var(--red);" onclick="peRemoveItem('${item.id}')">🗑️ حذف</button>
      </div>
      ${peItemFormFieldsHtml(item)}
    </div>`).join('');
}

function peItemImageUpload(itemId, which, fileList, append = false) {
  const files = Array.from(fileList || []);
  if (!files.length) return;
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = e => peSetItemPendingImage(itemId, which, e.target.result, file.type === 'image/gif', append || files.length > 1);
    reader.readAsDataURL(file);
  });
  document.getElementById(`peItemFile_${itemId}_${which}`).value = '';
}

function peSetItemPendingImage(itemId, which, dataUrl, isGif, append = false) {
  const apply = (val) => {
    const item = pePendingItems.find(it => it.id === itemId);
    if (item) {
      const field = which === 'base' ? 'base_image' : (which === 'abnormal' ? 'abnormal_content' : 'normal_content');
      if (append && field !== 'base_image') {
        const prev = Array.isArray(item[field]) ? item[field] : (item[field] ? [item[field]] : []);
        item[field] = [...prev, val];
      } else {
        item[field] = val;
      }
    }
    renderPePendingItemsForm();
  };
  if (isGif) { apply(dataUrl); return; } // never recompress GIFs — it kills the animation
  compressImageDataUrl(dataUrl, apply, 1400, 0.82);
}

document.addEventListener('paste', (e) => {
  const peArea = document.getElementById('peFormArea');
  if (!peArea || peArea.style.display === 'none' || !pePasteTarget) return;
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const clipItem of items) {
    if (clipItem.type && clipItem.type.startsWith('image/')) {
      const file = clipItem.getAsFile();
      if (!file) continue;
      e.preventDefault();
      const target = pePasteTarget;
      const isGif = clipItem.type === 'image/gif';
      const reader = new FileReader();
      reader.onload = ev => { peSetItemPendingImage(target.itemId, target.which, ev.target.result, isGif); showToast('✅ تم لصق الصورة'); };
      reader.readAsDataURL(file);
      break;
    }
  }
});

async function peSaveStep() {
  const title = document.getElementById('peTitleInput').value.trim();
  const prevEntry = peCurrentId ? peSteps.find(s => s.id === peCurrentId) : null;
  const prevCategory = prevEntry?.category;
  const entry = {
    id: peCurrentId || genId(),
    category: document.getElementById('peCategoryInput').value,
    title,
    sequence: Number(document.getElementById('peSequenceInput').value) || 0,
    stage_label: document.getElementById('peStageLabelInput').value.trim(),
    media_items: pePendingItems,
    createdAt: new Date().toLocaleString('ar-EG'),
  };
  try {
    await idbPutPeStep(entry);
  } catch (e) {
    console.error('peSaveStep failed', e);
    showToast('⚠️ فشل الحفظ فعليًا (الملفات كبيرة جدًا على الأغلب) — الخطوة ما انحفظت، جرب صور/فيديو أصغر أو رابط يوتيوب بدل الرفع المباشر');
    return;
  }
  if (peCurrentId) {
    const idx = peSteps.findIndex(s => s.id === peCurrentId);
    if (idx >= 0) peSteps[idx] = entry; else peSteps.push(entry);
    if (prevCategory && prevCategory !== entry.category) {
      peCategoryCounts[prevCategory] = Math.max(0, (peCategoryCounts[prevCategory] || 1) - 1);
      peCategoryCounts[entry.category] = (peCategoryCounts[entry.category] || 0) + 1;
      if (peCompleted.has(entry.id)) {
        peCompletedCountByCategory[prevCategory] = Math.max(0, (peCompletedCountByCategory[prevCategory] || 1) - 1);
        peCompletedCountByCategory[entry.category] = (peCompletedCountByCategory[entry.category] || 0) + 1;
        savePeCompletedCountByCategory();
      }
    }
  } else {
    peSteps.push(entry);
    peCategoryCounts[entry.category] = (peCategoryCounts[entry.category] || 0) + 1;
  }
  peLoadedCategories.add(entry.category);
  showToast('✅ تم حفظ الخطوة فعليًا');
  peActiveCategory = entry.category;
  localStorage.setItem('drmonic_pe_active_category', entry.category);
  peShowFlowchart();
}


